<template><div class="min-h-full bg-background p-3 md:p-4"><div class="mx-auto max-w-5xl"><div v-if="error" class="border border-red-200 bg-red-50 p-3 text-xs text-red-700">{{error}}</div><div v-else class="border border-slate-200 bg-white shadow-sm"><div class="flex items-center justify-between border-b border-slate-200 px-4 py-3"><div><p class="text-[10px] font-semibold uppercase tracking-wide text-primary">Offplan financing</p><h1 class="mt-0.5 text-lg font-bold text-slate-900">{{item.bank_name||'Bank financing'}}</h1></div><button @click="editOpen=true" class="border border-primary px-3 py-1.5 text-xs font-semibold text-primary">Edit</button></div><div class="grid gap-2 p-3 sm:grid-cols-2 lg:grid-cols-3"><div v-for="(v,k) in fields" :key="k" class="min-h-14 border border-slate-200 px-3 py-2"><p class="text-[10px] font-semibold uppercase tracking-wide text-slate-500">{{label(k)}}</p><p class="mt-0.5 text-xs font-semibold text-slate-900">{{format(v)}}</p></div></div></div></div><EditOffplanBankFinancing :open="editOpen" :id="id" @close="editOpen=false" @saved="load"/></div></template>
<script>import EditOffplanBankFinancing from "./EditOffplanBankFinancing.vue";export default{name:"OffplanBankFinancingDetail",components:{EditOffplanBankFinancing},props:{id:[String,Number]},data(){return{item:{},error:"",editOpen:false}},computed:{fields(){const x=this.item;return{bank_name:x.bank_name,loan_account_number:x.loan_account_number,loan_amount:x.loan_amount,interest_rate:x.interest_rate,loan_term_months:x.loan_term_months,monthly_payment:x.monthly_payment,loan_status:x.loan_status,approved_at:x.approved_at,first_payment_date:x.first_payment_date,application:this.rel(x.application),notes:x.notes}}},mounted(){this.load()},methods:{async load(){try{const r=await this.$apiGetById("/get_offplan_bank_financing",this.id);this.item=r?.data?.data||r?.data||r?.financing||r}catch(e){this.error=e?.message||"Unable to load financing."}},rel(v){return v&&typeof v==="object"?(v.name||v.title||v.application_number||v.reference||v.id||"—"):v??"—"},label(v){return v.replace(/_/g," ").replace(/\b\w/g,c=>c.toUpperCase())},format(v){return v??"—"}}};</script>